            this.getView().byId("multiInputPrompt").setEditable(true);
            this.getView().byId("multiInputPrompt").setEnabled(true);
            this.getView().byId("cancelPrmBtn").setVisible(false);
            this.getView().byId("addPrPart").setVisible(false);
